const fs = require('node:fs');
const path = require('node:path');
const {createHash}=require('node:crypto');
const {Worker}=require('node:worker_threads');

const root=path.resolve('src');
const files=new Map(), fileDigests={};
const hash=createHash('sha256');
for(const [group,suffix] of [['data','.csv'],['game_logic','.js'],['ui','.js'],['assets/art/faces','.js']]){
    const folder=path.join(root,group);
    for(const name of fs.readdirSync(folder).filter(x=>x.endsWith(suffix)).sort()){
        const key=path.join(folder,name), content=fs.readFileSync(key);
        files.set(key,content.toString('utf8'));
        hash.update(group+'/'+name+':');
        hash.update(content);
        fileDigests[group+'/'+name]=createHash('sha256').update(content).digest('hex');
    }
}
const input=hash.digest('hex');

const totalWorkers=12,nSeeds=24;
const checkpoints=null;
const workerSource="const {parentPort,workerData}=require('node:worker_threads');
const path=require('node:path');
const {SourceTextModule}=require('node:vm');
const {root,files,input,lane,totalWorkers,nSeeds,checkpoints}=workerData;
const fs=require('node:fs');
globalThis.saveDeparture=(seed,stage,g,at)=>{
    const g0=structuredClone(g);
    g0.reports=[];
    fs.writeFileSync(path.join(checkpoints,seed+'-'+stage+'.json'),JSON.stringify({input,seed,stage,at,g:g0}));
};
const modules=new Map();
function frozenRead(file){
    if(!files.has(file))throw Error('file outside snapshot: '+file);
    return files.get(file);
}
globalThis.location = {hostname: 'localhost'};
globalThis.fetch = async uri => ({ok:true,text:async()=>frozenRead(path.join(root,uri))});
function load(spec, parent) {
    const id = spec.startsWith('/') ? path.join(root,spec) : path.resolve(path.dirname(parent.identifier),spec);
    if(!modules.has(id)) {
        const code=frozenRead(id);
        modules.set(id,new SourceTextModule(code,{identifier:id}));
    }
    return modules.get(id);
}
const script = `
import {loadData,buildSystems,D,monsterName,placeName} from '/ui/data.js';
import {makeRng} from '/game_logic/rng.js';
import {createFormula} from '/game_logic/formula.js';
import {ROUND_GAP_MS,paceAt,paceStep,paceCfg} from '/ui/pace.js';
await loadData('/data/');
const b=D.balance;
const sys=buildSystems(D), q=sys.game;
const order=D.stageOrder.filter(id=>D.stages[id].chapter<=D.balance.chapter_open_max);
const bossStages=order.filter(id=>['standard','boss_only'].includes(D.stages[id].round_set));
const bossSet=new Set(bossStages);
globalThis.stageMeta=order.map(id=>{
    const s=D.stages[id];
    return {id,chapter:s.chapter,stage:s.stage_num,cell:s.cell,grade:s.boss_grade,name:s.boss_grade==='chapter_boss'?monsterName(s.boss_monster_idx).ko:placeName(s).ko};
});
const end=5051;
if(order.at(-1)!==end) throw Error('normal final boss differs from Baalzebub');
const dif='normal', start=1700000000000;
const potions=['healing','light_healing','minor_healing'];
const parts=['weapon','armor','helmet','gloves','boots'];
const bootRanks={tavern:1,shop:1,forge:1,storage:2,resource:2,command:1};
function skillValue(h,def,defend=false,element='physical') {
    if(defend){const s=tankBook(h,def,element);if(s!==null)return s;}
    if(!def)return 0;
    if(def.classId!==h.cls)return def.effectOnly?20:0;
    const attack=def.effects.some(row=>row.effect==='hit');
    const heal=def.effects.some(row=>row.effect==='heal');
    if(h.cls==='priest'){
        if(h.innate==='pri_judgment'&&heal)return def.id==='pri_heal'?100:95;
        if(h.innate!=='pri_judgment'&&def.id==='pri_judgment')return 100;
        return def.effectOnly?65:(heal||attack?60:50);
    }
    if(h.cls==='knight'){
        const shields=['kni_resistshield','kni_holyshield','kni_defiance'];
        return shields.includes(h.innate)?(attack?90:60):(shields.includes(def.id)?90:attack?70:60);
    }
    return attack?85:55;
}
function chooseBook(g,h,defend=false,element='physical') {
    const weapon=sys.item.groupOf(g.items[h.equipped.weapon]);
    const current=skillValue(h,sys.skill.defs[h.bookSkill],defend,element);
    const candidates=q.bookState(g,h.uid).books.flatMap(x=>{
        const d=sys.skill.defs[x.id], value=skillValue(h,d,defend,element);
        if(x.plan.err||!value||!sys.skill.fitsWeapon(d,weapon?.classes))return [];
        return [{...x,value}];
    }).sort((a,z)=>z.value-a.value||a.id.localeCompare(z.id,'en'));
    return candidates.find(x=>x.plan.act==='learn'&&x.value>current)
        ??candidates.find(x=>x.plan.act==='upgrade');
}
function learnBooks(g,h,now,defend=false,element='physical'){
    if(h.level<b.skillbook_learn_level)return;
    const pick=chooseBook(g,h,defend,element);
    if(pick)q.learnBook(g,h.uid,pick.id,now);
}
function auditLoadout(g,h) {
    const weapon=sys.item.groupOf(g.items[h.equipped.weapon]);
    if(h.bookSkill&&!sys.skill.fitsWeapon(sys.skill.defs[h.bookSkill],weapon?.classes))
        throw Error('book cannot cast '+h.cls+' '+h.bookSkill+' '+(weapon?.id??'none'));
}
globalThis.smokeBooks = () => {
    const candidates=starterProfile(1,7);
    const g=q.newGame(1,candidates,start);
    const priest=party(g).find(h=>h.cls==='priest');
    priest.level=10;
    priest.innate='pri_heal';
    g.books={war_bash:2,pri_judgment:1,pri_cure:1};
    const weapon=sys.item.groupOf(g.items[priest.equipped.weapon]);
    if(!weapon||sys.skill.fitsWeapon(sys.skill.defs.war_bash,weapon.classes))throw Error('incompatible skill check');
    const selected=chooseBook(g,priest);
    if(selected?.id!=='pri_judgment')throw Error('unexpected '+JSON.stringify(selected));
    const learned=q.learnBook(g,priest.uid,selected.id,start);
    if(!learned.ok)throw Error('book smoke learn '+learned.err);
    auditLoadout(g,priest);
    const played=once(g,1011,start,null,true,{combat:0});
    const casts=[...new Set(played.run.result.timeline.filter(e=>e.e==='skill'&&e.u?.startsWith('p')).map(e=>e.s))];
    if(!casts.includes('pri_judgment')||!casts.includes('pri_heal')||casts.includes('war_bash'))
        throw Error('book was not active '+JSON.stringify(casts));
    return {book:selected.id,weapon:weapon.id,casts};
};

const party=g=>q.partyOf(g).map(uid=>q.heroById(g,uid));
const upper=g=>Math.max(...party(g).map(h=>h.level));
const isBoss=stage=>D.stages[stage]?.boss_grade==='chapter_boss';
const F=createFormula(b), elems=['fire','cold','lightning','poison'];
const oneFront=g=>{const a=q.formationState(g,1).ranks[0];return a.length===1?q.heroById(g,a[0]):null;};
function durability(c,el){
    const phys=1-F.mitigation(c.defense);
    const take=e=>1-F.appliedResist(c['res_'+e],c.res_max_bonus,c.res_max_el?.[e]);
    const elemental=elems.includes(el);
    const damage=(elemental?(phys+take(el))/2:0.75*phys+0.0625*elems.reduce((s,e)=>s+take(e),0))*(1-c.damage_reduction);
    return (c.hp_max+12*c.hp_regen)/Math.max(0.025,damage);
}
function tankEquip(g,h,el){
    let n=0;
    for(const {id,part} of D.equipSlots){
        const get=it=>{
            if(part==='weapon')return it?sys.item.autoEquipScore(it,sys.skill.equipFit(h,sys.item.groupOf(it)?.damageKind),h.level,h.cls):-Infinity;
            return durability(q.heroCombat(g,it?{...h,equipped:{...h.equipped,[id]:it.uid}}:h),el);
        };
        let best=null,value=get(g.items[h.equipped[id]]);
        for(const uid of g.bags[0]){
            const it=g.items[uid];
            if(!it||it.box||it.slot!==part||sys.item.canEquip(h,it)||!sys.item.fitsClass(it,h.cls))continue;
            const x=get(it);if(x>value+1e-7){best=it;value=x;}
        }
        if(best){const r=q.equip(g,h.uid,best.uid,id);if(!r.ok)throw Error('tank gear '+r.err);n++;}
    }
    return n;
}
function tankMastery(g,h,ns,el){
    if(ns.length<2)return ns[0];
    let best=ns[0],score=-Infinity;
    h.mastery??={};
    for(const n of ns){
        const v=h.mastery[n.id];h.mastery[n.id]=(v??0)+1;
        const x=durability(q.heroCombat(g,h),el);
        if(v===undefined)delete h.mastery[n.id];else h.mastery[n.id]=v;
        if(x>score+1e-7){best=n;score=x;}
    }
    return best;
}
const defenseBooks={warrior:['war_ironskin','war_recovery','war_shout'],knight:['kni_defiance','kni_resistshield','kni_holyshield','war_ironskin','war_shout']};
function tankBook(h,d,el){
    const i=(defenseBooks[h.cls]??[]).indexOf(d?.id);
    if(i<0||h.innate===d.id)return null;
    if(d.id==='kni_resistshield'&&elems.includes(el))return 120;
    return 115-i;
}
const keyStages=new Set([1051,2051,3051,4011,4051,5021,5023,5031,5033,5051]);
function exposeFront(g){
    const h=oneFront(g);if(!h)return null;
    const c=q.heroCombat(g,h);
    return {uid:h.uid,cls:h.cls,hp:c.hp_max,def:c.defense,fire:c.res_fire,dr:c.damage_reduction,book:h.bookSkill??null,innate:h.innate};
}
globalThis.checkSoloPolicy=()=>{
    const one=q.newGame(3,starterProfile(3,3),start),two=q.newGame(3,starterProfile(3,1),start);
    const h=oneFront(one);
    if(h?.cls!=='warrior'||oneFront(two))throw Error('frontline selection');
    h.level=12;h.innate='war_bash';one.books={war_doubleswing:1,war_ironskin:1};
    if(chooseBook(one,h,true,'fire')?.id!=='war_ironskin')throw Error('solo book choice');
    learnBooks(one,h,start,true,'fire');auditLoadout(one,h);
    const r=once(one,1011,start,null,true,{combat:0});
    if(!r.run.result.timeline.some(e=>e.e==='skill'&&e.u?.startsWith('p')&&e.s==='war_ironskin'))throw Error('solo book did not cast');
    return {solo:h.cls,book:h.bookSkill,twoFront:q.formationState(two,1).ranks[0].length};
};

function manage(g,now,stage,counters,useDefense) {
    const front=useDefense?oneFront(g):null;
    const el=sys.battle.stageElement(D.stages[stage]);
    q.labSettle(g,now);
    for(const mission of q.mainMissionState(g).claimable)
        if(q.mainMissionClaim(g,mission.id).ok) counters.missions++;
    for(const [id,max] of Object.entries(bootRanks))
        if((g.buildings[id]??0)<max) q.construct(g,id,now);
    for(const mission of q.mainMissionState(g).claimable)
        if(q.mainMissionClaim(g,mission.id).ok) counters.missions++;
    for(const uid of [...g.stash,...g.bags[0]]) {
        const box=g.items[uid]?.box;
        if(!box) continue;
        const score=h=>box.kind==='weapon'?(g.items[h.equipped.weapon]?.ilvl??0):
            parts.slice(1).reduce((total,p)=>total+(g.items[h.equipped[p]]?.ilvl??0),0);
        const use=party(g).reduce((a,c)=>score(a)<=score(c)?a:c);
        const opened=q.openBox(g,uid,use.uid);
        if(opened.ok){
            counters.boxes++;
            if(g.stash.includes(opened.item)) q.moveToBag(g,opened.item,1);
        }
    }
    const order=front?[front,...party(g).filter(x=>x.uid!==front.uid)]:party(g);
    for(const h of order) {
        const defend=front?.uid===h.uid;
        counters.gear+=defend?tankEquip(g,h,el):q.autoEquip(g,h.uid,1).changes?.length??0;
        const previous=h.bookSkill;
        learnBooks(g,h,now,defend,el);
        if(previous!==h.bookSkill)counters.books++;
        auditLoadout(g,h);
        for(let i=0;i<60;i++){
            const nodes=q.masteryState(g,h.uid).nodes.filter(n=>n.canLearn);
            const node=defend?tankMastery(g,h,nodes,el):nodes[0];
            if(!node||!q.learnMastery(g,h.uid,node.id).ok) break;
            counters.mastery++;
        }
    }
    for(const uid of [...g.bags[0]]) {
        const it=g.items[uid];
        if(!it||it.box||it.locked||party(g).some(h=>sys.item.fitsClass(it,h.cls)&&sys.item.canEquip(h,it)==='level')) continue;
        q.salvage(g,uid);
    }
    const res=q.labState(g,now).lines.find(x=>x.line==='res');
    if(res?.open && res.seats.uids.length<res.seats.cap) {
        const h=party(g).filter(h=>!q.labRegOf(g,h.uid)).sort((a,c)=>c.stats.str-a.stats.str)[0];
        if(h) q.labRegister(g,h.uid,'res',now);
    }
    const lab=q.labState(g,now).lines.find(x=>x.line==='res');
    if(lab?.open && !g.labResearch && !Object.values(g.labNodes??{}).some(Boolean)){
        const node=lab.nodes.find(n=>!n.err && n.lv===0);
        if(node) q.labResearchStart(g,'res',node.node,now);
    }
    q.commissionFill(g);
    for(const cm of q.commissionState(g).cards)
        if(cm.taken&&cm.done) q.commissionClaim(g,cm.no);
    q.commissionFill(g);
    for(const cm of q.commissionState(g).cards)
        if(cm.canTake) q.commissionTake(g,cm.no);
    const slots=q.limitsOf(g).potionSlots, chapter=D.stages[stage].chapter;
    const wanted=chapter>=4?potions:chapter>=2?potions.slice(1):potions.slice(2);
    let remaining=slots*4;
    for(const id of wanted){
        const cost=q.shopPotionGold(id);
        const have=g.potions[id]??0;
        const buy=Math.max(0,Math.min(remaining-have,Math.floor(g.resources.gold/cost)));
        if(buy>0 && q.shopPotionBuy(g,id,buy).ok) counters.potionsBought+=buy;
        remaining=Math.max(0,remaining-(g.potions[id]??0));
    }
    const fill=potions.flatMap(id=>Array(Math.min(slots,g.potions[id]??0)).fill(id));
    for(let i=0;i<slots;i++) q.setPotionSlot(g,i,fill[i]??null);
    for(const h of party(g)) for(const part of ['weapon','armor']){
        const uid=h.equipped[part];
        if(!uid||(g.items[uid]?.up??0)>=3) continue;
        const view=q.upgradeState(g,uid);
        if(view?.canUpgrade && q.upgradeItem(g,uid).ok) counters.upgrades++;
    }
}
function once(g,stage,at,from,checked,timing) {
    const open=q.departRun(g,stage,at,1,from,dif);
    if(!open.ok) throw Error('depart '+stage+' '+open.err);
    if(!q.stepRun(g,open.run,Infinity).done) throw Error('unfinished run '+stage);
    const {run,report}=open, tl=run.result.timeline;
    const end=tl.at(-1);
    if(end.e!=='end') throw Error('missing timeline end '+stage);
    const gaps=tl.filter(ev=>ev.e==='round').length-1;
    const elapsed=Math.round(end.t*1000)+Math.max(0,gaps)*ROUND_GAP_MS;
    if(checked===false){
        const at=paceAt(tl,0), remaining=paceStep(at,tl,700000,paceCfg('off',false,1));
        if(!at.done || Math.abs(elapsed-(700000-remaining))>1) throw Error('clock disagreement');
    }
    timing.combat+=end.t*1000;
    const ended=at+elapsed;
    q.addExpTime(g,end.t*1000);
    q.noteRunEnd(g,run,ended);
    return {run,report,ended,elapsed};
}

const profiles=[
 ['warrior','knight','mage'],['warrior','knight','archer'],['warrior','knight','priest'],
 ['warrior','mage','archer'],['warrior','mage','priest'],['warrior','archer','priest'],
 ['knight','mage','archer'],['knight','mage','priest'],['knight','archer','priest'],
];
const orders=[[0,1,2],[0,2,1],[1,0,2],[1,2,0],[2,0,1],[2,1,0]];
globalThis.profiles=profiles;
function starterProfile(seed,profile) {
    const classes=orders[(seed-1)%orders.length].map(i=>profiles[profile][i]);
    const rng=makeRng((Math.imul(seed,0x9e3779b9)^0x9c456f19)>>>0);
    for(let tries=0;tries<4096;tries++){
        const party=sys.hero.rollStartParty(rng,b.party_size_max);
        if(party.every((h,i)=>h.cls===classes[i]))return party;
    }
    throw Error('starter order not found '+classes.join(','));
}
globalThis.runPace = (seed,capHours,verify,profile,useDefense) => {
    const g=q.newGame(seed,starterProfile(seed,profile),start);
    const cls=party(g).map(h=>h.cls);
    const frontTrace={};
    const state={stage:order[0],at:start,from:null};
    let rooms=0,nextManagement=start,finish=null,stage5_2At=null,l30=null,farm=null,losses=0,lastLoss=null;
    const first={}, firstClear={}, firstBoss={}, paired={}, bosses=[], entered={}, results={}, timing={combat:0}, counters={missions:0,boxes:0,gear:0,books:0,mastery:0,upgrades:0,potionsBought:0,potionsUsed:0,farmRuns:0,changedPotions:0};
    let furthest=0, endAt=start;
    while(state.at-start<capHours*3600000){
        const {at,stage}=state;
        const onFarm=!!farm;
        if(at>=nextManagement){
            manage(g,at,order[furthest],counters,useDefense);
            nextManagement=start+(Math.floor((at-start)/300000)+1)*300000;
        }
        const slots=g.presets[0].potionSlots??[];
        const previous=state.from?.squad.potionSlots;
        const changed=previous && Array.from({length:Math.max(previous.length,slots.length)},(_,i)=>(previous[i]??null)===(slots[i]??null)).includes(false);
        if(changed) counters.changedPotions++;
        if(onFarm)counters.farmRuns++;
        const beforeLv=upper(g), beforePots=Object.values(g.potions).reduce((s,n)=>s+n,0);
        entered[stage]??=(at-start)/60000;
        const held=changed?null:state.from;
        const record=!first[stage];
        const levelsAtArrival=record?party(g).map(h=>h.level):null;
        const selected=record&&keyStages.has(stage)?exposeFront(g):null;
        const stock=selected?(g.potions.healing??0):0;
        const played=once(g,stage,at,held,verify&&rooms===0?false:true,timing);
        const {run,report,ended}=played;
        if(selected){
            const id='p'+run.party.indexOf(selected.uid);
            const tl=run.result.timeline;
            const down=tl.find(e=>e.e==='down'&&e.u===id);
            frontTrace[stage]={...selected,fall:down?.t??null,round:run.result.rounds.at(-1)?.n,sec:run.result.durationSec,
                stock,cast:tl.filter(e=>e.e==='skill'&&e.u===id&&e.s===selected.book).length};
        }
        if(record){
            const level=levelsAtArrival.reduce((sum,x)=>sum+x,0)/levelsAtArrival.length;
            first[stage]=[Number(report.won),Math.round((at-start)/1000),+level.toFixed(3),+(played.elapsed/1000).toFixed(1)];
        }
        if(report.won && firstClear[stage]===undefined)firstClear[stage]=Math.round((ended-start)/1000);
        if(bossSet.has(stage)&&!firstBoss[stage]){
            const bossRound=run.result.rounds.find(r=>r.kind==='boss');
            if(bossRound)firstBoss[stage]=[Number(run.result.roundsCleared>=bossRound.n),beforeLv,results[stage]?.losses??0];
        }
        endAt=ended; rooms++;
        (results[stage]??={wins:0,losses:0,minutes:0})[report.won?'wins':'losses']++;
        results[stage].minutes+=played.elapsed/60000;
        counters.potionsUsed+=beforePots-Object.values(g.potions).reduce((s,n)=>s+n,0);
        const levels=party(g).map(h=>h.level);
        if(l30===null&&Math.max(...levels)>=30) l30=(ended-start)/60000;
        if(report.won && isBoss(stage)&&!bosses.some(x=>x.stage===stage)) bosses.push({stage,minutes:(ended-start)/60000,levels});
        if(report.won && stage===end){
            const top=party(g).reduce((a,c)=>a.level>c.level||a.level===c.level&&a.xp>=c.xp?a:c);
            const xpLeft=top.level>=30?0:Array.from({length:30-top.level},(_,i)=>sys.hero.xpNeeded(top.level+i)).reduce((a,c)=>a+c,0)-top.xp;
            finish={minutes:(ended-start)/60000,combatMinutes:timing.combat/60000,levels,beforeLv,highest:top.level,xpLeft,gold:g.resources.gold,xp:top.xp};
            break;
        }
        if(report.won && stage===order[furthest]) furthest++;
        const next=q.nextRepeat(g,ended,1);
        if(!next) throw Error('no repeat after '+stage);
        let nextStage=next.stageId,from=run;
        if(farm){
            farm.remaining--;
            nextStage=farm.remaining>0?farm.stage:farm.target;
            from=null;
            if(!farm.remaining) farm=null;
        }else if(!report.won && stage===order[furthest] && !isBoss(stage)){
            losses=lastLoss===stage?losses+1:1; lastLoss=stage;
            if(losses===10){
                const prev=order.slice(0,furthest).reverse().find(id=>!isBoss(id)&&q.stageCleared(g,id,dif));
                if(prev){
                    farm={stage:prev,target:stage,remaining:10};
                    nextStage=prev;
                    from=null;
                    losses=0;
                }
            }
        }else if(report.won && stage===lastLoss){losses=0;lastLoss=null;}
        state.stage=nextStage;
        state.at=nextStage===next.stageId?next.at:ended+b.repeat_restart_sec*1000;
        state.from=from;
    }
    return {seed,cls,finish,bosses,l30,rooms,farmRuns:counters.farmRuns,potionsUsed:counters.potionsUsed,entered5_2:entered[5021]??null,passed5_2:entered[5031]??null,elapsed:(endAt-start)/60000,front:order[furthest],first,firstClear,firstBoss,paired,frontTrace};
};
`;
(async()=>{
 const entry=new SourceTextModule(script,{identifier:path.join(root,'_party_profile_campaign.js')});
 await entry.link(load);
 await entry.evaluate();
 if(lane===0){
    const smoke={books:globalThis.smokeBooks(),solo:globalThis.checkSoloPolicy()};
    parentPort.postMessage({meta:globalThis.stageMeta,profiles:globalThis.profiles,input,smoke,checkpoints});
    await new Promise(resolve=>parentPort.once('message',resolve));
 }
 const jobs=globalThis.profiles.map((_,i)=>[i,i>=3]);
 for(let idx=lane;idx<nSeeds*jobs.length;idx+=totalWorkers){
    const seed=Math.floor(idx/jobs.length)+1, [profile,defense]=jobs[idx%jobs.length];
    const began=performance.now();
